export interface AdminRequest {
  method: string;
  path: string;
  headers: Record<string, string>;
  actor: string;
}

export interface AuditEntry {
  [field: string]: unknown;
}

/** One audit entry for an admin action, as stored for the SOC 2 evidence. */
export function auditEntry(req: AdminRequest, action: string, now: Date = new Date()): AuditEntry {
  return {
    timestamp: now.toISOString(),
    actor: req.actor,
    action,
    method: req.method,
    path: req.path,
    sourceIp: req.headers["x-forwarded-for"] || req.headers["x-real-ip"] || "unknown",
    userAgent: req.headers["user-agent"] || "unknown",
  };
}
